// Seitenleiste mit zwei Tabs. Chat: Schnellfragen + Eingabe; Guide: die fünf Schritte kompakt.
export function AssistantPanel({
  isOpen, tab, onTab, onToggle, messages, busy, onSend,
}: {
  isOpen: boolean; tab: Tab; onTab: (t: Tab) => void; onToggle: () => void;
  messages: Message[]; busy: boolean; onSend: (text: string) => void;
}) {
  const [text, setText] = useState("");
  const listRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
  }, [messages, busy]);
  useEffect(() => {
    if (isOpen && tab === "chat") inputRef.current?.focus();
  }, [isOpen, tab]);

  return (
    <>
      <button
        type="button"
        aria-label={isOpen ? "Close assistant" : "Open assistant"}
        aria-expanded={isOpen}
        onClick={onToggle}
        className="group fixed bottom-6 right-6 z-[60] flex h-14 items-center bg-[var(--blue)] text-white shadow-[0_8px_30px_rgba(28,105,212,0.35)] transition-colors hover:bg-[var(--blue-hover)]"
      >
        {!isOpen && <span className="absolute inset-0 animate-ping bg-[var(--blue)] opacity-20 [animation-iteration-count:3]" aria-hidden="true" />}
        <span className="flex h-14 w-14 items-center justify-center"><Icon name={isOpen ? "close" : "chat"} /></span>
        {!isOpen && (
          <span className="max-w-0 overflow-hidden whitespace-nowrap text-sm font-semibold transition-[max-width,padding] duration-300 group-hover:max-w-40 group-hover:pr-5">
            Ask Signal2Spec
          </span>
        )}
      </button>

      <aside
        aria-label="Signal2Spec assistant"
        aria-hidden={!isOpen}
        className={`fixed bottom-0 right-0 top-0 z-50 flex w-full max-w-[420px] flex-col border-l border-[var(--hairline)] bg-white shadow-[-20px_0_60px_rgba(0,0,0,0.12)] transition-transform duration-300 ease-out ${
          isOpen ? "translate-x-0" : "pointer-events-none translate-x-full"
        }`}
      >
        <header className="bg-[var(--black)] px-6 pb-0 pt-6 text-white">
          <div className="flex items-center justify-between">
            <Logo light size={28} />
            <span className="text-[10px] font-semibold uppercase tracking-[0.16em] text-white/50">Assistant</span>
          </div>
          <nav className="mt-6 flex gap-6" aria-label="Assistant tabs">
            {(["chat", "guide"] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => onTab(t)}
                className={`border-b-2 pb-3 text-sm font-semibold capitalize ${tab === t ? "border-[var(--m-light)] text-white" : "border-transparent text-white/50 hover:text-white"}`}
              >
                {t}
              </button>
            ))}
          </nav>
        </header>

        {tab === "guide" ? (
          <GuideTab />
        ) : (
          <>
            <div ref={listRef} className="flex flex-1 flex-col gap-4 overflow-y-auto px-6 py-6">
              {messages.map((m, i) => <Bubble key={i} m={m} />)}
              {busy && <p className="self-start bg-[var(--grey-100)] px-4 py-3 text-sm text-[var(--grey-500)]">Looking through the data…</p>}
              {messages.length <= 1 && (
                <div className="flex flex-wrap gap-2">
                  {QUICK.map((q) => (
                    <button key={q} type="button" onClick={() => onSend(q)} className="border border-[var(--hairline)] px-3 py-1.5 text-xs text-[var(--ink)] hover:border-[var(--ink)]">
                      {q}
                    </button>
                  ))}
                </div>
              )}
            </div>
            <form
              className="flex border-t border-[var(--hairline)]"
              onSubmit={(e) => {
                e.preventDefault();
                onSend(text);
                setText("");
              }}
            >
              <input
                ref={inputRef}
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="Ask about the data or where to go…"
                aria-label="Message to the assistant"
                className="h-14 flex-1 px-5 text-sm focus:outline-none"
              />
              <button type="submit" disabled={busy || !text.trim()} aria-label="Send" className="flex w-14 items-center justify-center text-[var(--blue)] disabled:text-[var(--grey-500)]">
                <Icon name="arrow" />
              </button>
            </form>
            {messages.length > 1 && (
              <div className="flex gap-2 overflow-x-auto border-t border-[var(--hairline)] px-4 py-2">
                {QUICK.slice(0, 4).map((q) => (
                  <button key={q} type="button" onClick={() => onSend(q)} className="shrink-0 px-2 py-1 text-[11px] text-[var(--grey-500)] hover:text-[var(--ink)]">
                    {q}
                  </button>
                ))}
              </div>
            )}
            <p className="px-6 pb-20 pt-1 text-[10px] text-[var(--grey-500)] sm:pb-3">Answers cite only requirements that exist in the data.</p>
          </>
        )}
      </aside>
    </>
  );
}

import Link from "next/link";
import { EvidenceDot } from "@/src/components/badges";

// Kompakter Guide im Assistenten: der Demo-Weg in fünf Schritten plus Ampel-Legende.
// Die ausführliche Seite /guide bleibt für Deep-Links.
const STEPS = [
  ["Pick a model and market", "Scenario selector in the header, or the cards on the home page."],
  ["Ask in your own words", "Top of the cockpit. The AI only sets weights; Python ranks. Apply re-ranks the list."],
  ["Open a row", "Customer voices left, decision right, score math below."],
  ["Decide", "Approve, reject, edit or challenge. A rationale is required."],
  ["Check the audit trail", "Every change with person, time and reason, hash-chained."],
];

const LIGHTS = [
  ["A", "Proven", "many customer voices, several sources"],
  ["C", "Weak", "little evidence, treat with care"],
  ["D", "Assumption", "trend or idea without direct voices"],
] as const;

export function GuideTab() {
  return (
    <div className="flex-1 overflow-y-auto px-6 py-6">
      <ol className="grid gap-5">
        {STEPS.map(([title, text], i) => (
          <li key={title} className="flex gap-4">
            <span className="text-2xl font-extralight tabular-nums text-[var(--blue)]">{i + 1}</span>
            <span>
              <span className="block font-semibold text-[var(--ink)]">{title}</span>
              <span className="mt-1 block text-sm text-[var(--grey-500)]">{text}</span>
            </span>
          </li>
        ))}
      </ol>
      <p className="mt-8 text-xs font-semibold uppercase tracking-[0.16em] text-[var(--grey-500)]">Evidence traffic light</p>
      <ul className="mt-3 grid gap-2">
        {LIGHTS.map(([level, word, text]) => (
          <li key={word} className="flex items-center gap-3 text-sm">
            <EvidenceDot level={level} />
            <span className="font-semibold text-[var(--ink)]">{word}</span>
            <span className="text-[var(--grey-500)]">{text}</span>
          </li>
        ))}
      </ul>
      <Link href="/guide" className="mt-8 inline-block text-sm font-semibold text-[var(--blue)] hover:text-[var(--blue-hover)]">
        Full guide with every function →
      </Link>
    </div>
  );
}

